"""Concept notes per official chapter (bilingual). Each entry:
s = summary, k = key ideas/rules, p = prerequisite, m = common mistakes, x = exam connection,
pw = pathway tips (F, G, A), c = extra flashcards (q_en, a_en, q_ta, a_ta)."""
from core import T

def N(s, k, p, m, x, pw, c):
    return dict(s=T(*s), k=[T(*i) for i in k], p=T(*p), m=[T(*i) for i in m], x=T(*x), pw=[T(*i) for i in pw], c=c)

